CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,display_name text NOT NULL DEFAULT '',avatar_url text NOT NULL DEFAULT '');
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.cms_auth_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'display_name','')) ON CONFLICT DO NOTHING; IF lower(NEW.email)='kchaudhary@e-works.co.uk' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'admin') ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER cms_profile_created AFTER INSERT OR UPDATE OF email_confirmed_at ON auth.users FOR EACH ROW EXECUTE FUNCTION public.cms_auth_profile();
CREATE TABLE public.cms_documents (id text PRIMARY KEY CHECK(id IN ('published','draft')),document jsonb NOT NULL,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid);
GRANT SELECT ON public.cms_documents TO anon; GRANT SELECT,UPDATE ON public.cms_documents TO authenticated; GRANT ALL ON public.cms_documents TO service_role;
ALTER TABLE public.cms_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY published_read ON public.cms_documents FOR SELECT TO anon,authenticated USING(id='published');
CREATE POLICY admin_document_read ON public.cms_documents FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_document_update ON public.cms_documents FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.cms_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid,action text NOT NULL);
GRANT SELECT,INSERT ON public.cms_revisions TO authenticated; GRANT ALL ON public.cms_revisions TO service_role;
ALTER TABLE public.cms_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_revisions_read ON public.cms_revisions FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_revisions_insert ON public.cms_revisions FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.cms_save(_document jsonb,_version integer,_publish boolean) RETURNS integer LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE next_version integer; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; UPDATE public.cms_documents SET document=_document,version=version+1,updated_at=now(),updated_by=auth.uid() WHERE id='draft' AND version=_version RETURNING version INTO next_version; IF next_version IS NULL THEN RAISE EXCEPTION 'Another administrator changed this content. Reload before saving.'; END IF; INSERT INTO public.cms_revisions(document,created_by,action) VALUES(_document,auth.uid(),CASE WHEN _publish THEN 'published' ELSE 'saved draft' END); IF _publish THEN UPDATE public.cms_documents SET document=_document,version=version+1,updated_at=now(),updated_by=auth.uid() WHERE id='published'; END IF; RETURN next_version; END $$;
REVOKE ALL ON FUNCTION public.cms_save(jsonb,integer,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.cms_save(jsonb,integer,boolean) TO authenticated;
CREATE POLICY admin_media_select ON storage.objects FOR SELECT TO authenticated USING(bucket_id='website-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_media_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='website-media' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY admin_media_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='website-media' AND public.has_role(auth.uid(),'admin'));
