andoff was clean and the launch metrics spoke for themselves.","name":"Daniel Mertens","role":"Head of Product, Nacre"},{"quote":"A rare studio that cares about craft and outcomes equally. We've doubled engagement since the redesign.","name":"Sofia Almeida","role":"CMO, Form & Field"}]},{"key":"awards","label":"Awards","title":"","description":"","enabled":true,"fields":{},"items":[{"award":"Awwwards","detail":"Site of the Day ×3"},{"award":"CSS Design Awards","detail":"Best UI ×2"},{"award":"FWA","detail":"Of the Day"},{"award":"The Webby Awards","detail":"Honoree"}]},{"key":"cta","label":"Call to action","title":"Have a project in mind?","description":"","enabled":true,"fields":{"accent":"Let's make it.","button":"Start a project"},"items":[{"text":"Available for new projects"},{"text":"Brand"},{"text":"Web"},{"text":"Motion"},{"text":"Product"},{"text":"Let's collaborate"}]},{"key":"navigation","label":"Navigation","title":"","description":"","enabled":true,"fields":{},"items":[{"label":"Work","href":"#work"},{"label":"Studio","href":"#studio"},{"label":"Process","href":"#process"},{"label":"Recognition","href":"#recognition"}]},{"key":"socials","label":"Social links","title":"","description":"","enabled":true,"fields":{},"items":[{"label":"Instagram","href":"#"},{"label":"Behance","href":"#"},{"label":"LinkedIn","href":"#"},{"label":"Awwwards","href":"#"}]}]}$seed$::jsonb FROM unnest(ARRAY['published','draft']) id;